(()=>{'use strict';
const M=window.ERP,KEY='aurelle-erp-demo-v1',main=document.querySelector('main'),dialog=document.querySelector('dialog');
let state=M.seed(),view='overview',search='',statusFilter='All',returnFocus=null,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.items)&&Array.isArray(saved.orders)&&Array.isArray(saved.hampers)&&Array.isArray(saved.quotes)&&Array.isArray(saved.activity))state=saved;}catch{}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v);
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',orders:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h4',inventory:'m3 7 9-4 9 4-9 4-9-4 M3 7v10l9 4 9-4V7 M12 11v10',hampers:'M3 9h18v4H3z M5 13v8h14v-8 M12 9v12 M12 9C2 9 6 0 10 5l2 4 M12 9c10 0 6-9 2-4l-2 4',corporate:'M4 21V7h16v14 M9 7V3h6v4 M8 11h2 M14 11h2 M8 15h2 M14 15h2 M10 21v-3h4v3',dispatch:'M2 6h12v12H2z M14 10h4l4 4v4h-8 M6 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',reports:'M4 3v18h17 M8 17v-5 M13 17V8 M18 17V4',plus:'M12 4v16 M4 12h16',arrow:'M5 12h14 M14 7l5 5-5 5',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',alert:'m12 3 10 18H2L12 3 M12 9v5 M12 17v1',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',rupee:'M6 4h12 M6 8h12 M8 4c9 0 9 8 0 8H6l10 8'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.overview}"/></svg>`;
const badge=value=>`<span class="badge ${String(value).toLowerCase().split(' ')[0]}"><i></i>${esc(value)}</span>`;
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const nextLabel=s=>s==='Confirmed'?'Start packing':s==='Packing'?'Mark ready':'Dispatch gifts';
const names={overview:'Overview',orders:'Orders',inventory:'Inventory',hampers:'Gift hampers',corporate:'Corporate gifting',dispatch:'Packing & dispatch',reports:'Reports'};
function toast(msg){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=msg;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Changes are temporary: browser storage is unavailable.');}}
function nav(){document.querySelector('#navigation').innerHTML=Object.entries(names).map(([id,name])=>`<a href="#${id}" class="nav-link ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}${name}${id==='orders'?`<span class="nav-count">${state.orders.filter(o=>M.activeStatuses.includes(o.status)).length}</span>`:''}</a>`).join('');document.querySelector('#breadcrumb').textContent=names[view];}
function heading(eyebrow,title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subheading">${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
const button=(label,action,extra='',primary=false)=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${icon(action==='export'?'download':'plus')}${label}</button>`;
function metrics(){const valid=state.orders.filter(o=>o.status!=='Cancelled');const booked=valid.reduce((n,o)=>n+o.qty*o.price,0);const active=valid.filter(o=>M.activeStatuses.includes(o.status));const low=state.items.filter(i=>M.available(state,i.id)<=i.min);return `<div class="metrics">${[
['Order value',money(booked),'rupee','<span class="green">'+valid.length+' orders</span> in the demo workspace'],['Active orders',active.length,'orders','<span class="green">'+active.reduce((n,o)=>n+o.qty,0)+' gifts</span> being thoughtfully prepared'],['Ready to dispatch',valid.filter(o=>o.status==='Ready').length,'dispatch','Packed, checked & ready to go'],['Stock attention',low.length,'inventory','<span class="amber">Components at or below reorder level</span>']].map(([label,value,ico,foot])=>`<div class="metric"><p class="metric-label">${label}</p><span class="metric-icon">${icon(ico)}</span><div class="metric-value">${value}</div><p class="metric-foot">${foot}</p></div>`).join('')}</div>`;}
function ordersTable(orders,compact=false){return `<div class="table-wrap"><table><thead><tr><th>ORDER / CUSTOMER</th>${compact?'':'<th>GIFT COLLECTION</th>'}<th>VALUE</th><th>STATUS</th>${compact?'':'<th>PAYMENT</th>'}<th>DUE</th><th><span class="visually-hidden">Details</span></th></tr></thead><tbody>${orders.map(o=>`<tr><td><button class="order-id" data-action="order-detail" data-id="${o.id}">${o.id}</button><small>${esc(o.customer)}</small></td>${compact?'':`<td>${esc(M.hamper(state,o.hamper)?.name)}<small>${o.qty} gift${o.qty===1?'':'s'} · ${esc(o.channel)}</small></td>`}<td>${money(o.qty*o.price)}</td><td>${badge(o.status)}</td>${compact?'':`<td>${badge(o.payment)}</td>`}<td>${date(o.due)}</td><td><button class="link-button" data-action="order-detail" data-id="${o.id}" aria-label="View order ${o.id}">↗</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No orders match your search.</td></tr>'}</tbody></table></div>`;}
function overview(){const bottleneck=M.item(state,M.bottleneck(state,state.hampers[0].recipe));return heading('THE ART OF GIVING, IN ORDER','A thoughtful day begins here.','Your boutique at a glance. Every gift, every detail, in one place.',`<span class="date-control">${icon('calendar')} Sample period · Oct–Nov 2026</span>${button('Create order','new-order','',true)}`)+metrics()+`<div class="layout"><div><section class="panel"><div class="panel-head"><div><h2>Recent orders</h2><p>A little care, at every stage.</p></div><a class="link-button" href="#orders">View all orders ↗</a></div>${ordersTable(state.orders.slice(0,5),true)}<div class="table-bottom"><span>${state.orders.length} orders in your workspace</span><span>Sample transactions</span></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>From order to doorstep</h2></div><div class="pipeline">${['Confirmed','Packing','Ready','Dispatched'].map(status=>{const n=state.orders.filter(o=>o.status===status).length;return `<div class="pipeline-line"><span>${status}</span><div class="bar-track"><div class="bar-fill" style="width:${n/Math.max(1,state.orders.length)*100}%"></div></div><span>${n}</span></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Studio activity</h2></div><div class="activity">${state.activity.slice(0,3).map(a=>`<div class="activity-row"><i class="activity-dot"></i><div>${esc(a.text)}<small>${esc(a.time)}</small></div></div>`).join('')}</div></section></div></div><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Ready to be gifted</h2><p>Buildable from available components.</p></div></div><div class="capacity-list">${state.hampers.slice(0,3).map(h=>`<button class="capacity-item" style="width:100%;text-align:left" data-action="new-order" data-hamper="${h.id}"><img class="thumb" src="../assets/${h.image}" alt=""><span class="capacity-copy"><strong>${esc(h.name)}</strong><small>${money(h.price)} / gift</small></span><span class="capacity-value">${M.capacity(state,h.recipe)}<small>available</small></span></button>`).join('')}</div><div class="stock-note">${icon('alert')}<span>${esc(bottleneck.name)} limits Signature availability. <a href="#inventory"><u>Review stock</u></a></span></div></section><section class="promo"><img src="../assets/gift-atelier.jpg" alt="Ivory gift boxes with burgundy ribbon"><div class="promo-copy"><p class="eyebrow">FOR THEIR PEOPLE</p><h2>Big gestures.<br><em>Beautifully managed.</em></h2><p>Bring corporate and celebration gifting together.</p><a href="#corporate" class="link-button">Explore bespoke gifting ↗</a></div></section></div></div>`;}
function orders(){const rows=state.orders.filter(o=>(statusFilter==='All'||o.status===statusFilter)&&`${o.id} ${o.customer} ${M.hamper(state,o.hamper)?.name}`.toLowerCase().includes(search.toLowerCase()));return heading('EVERY GIFT HAS A STORY','Orders','From a first thought to a beautiful delivery.',button('Export CSV','export')+button('Create order','new-order','',true))+`<section class="panel"><div class="toolbar"><div class="filters">${['All',...M.activeStatuses,'Dispatched','Cancelled'].map(s=>`<button class="filter ${statusFilter===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><input class="search" aria-label="Search orders" placeholder="Search orders or customers…" value="${esc(search)}"></div>${ordersTable(rows)}<div class="table-bottom">${rows.length} of ${state.orders.length} orders · amounts are illustrative</div></section>`;}
function inventory(){const items=state.items.filter(i=>`${i.name} ${i.sku} ${i.category}`.toLowerCase().includes(search.toLowerCase())&&(statusFilter!=='Low stock'||M.available(state,i.id)<=i.min));return heading('A PLACE FOR EVERY DETAIL','Inventory','Components and packaging, with order reservations kept in view.',button('Export CSV','export'))+`<section class="panel"><div class="toolbar"><div class="filters">${['All','Low stock'].map(s=>`<button class="filter ${statusFilter===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><input class="search" aria-label="Search inventory" placeholder="Search components or SKU…" value="${esc(search)}"></div><div class="table-wrap"><table><thead><tr><th>COMPONENT</th><th>ON HAND</th><th>RESERVED</th><th>AVAILABLE</th><th>UNIT COST</th><th>STOCK LEVEL</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${i.sku} · ${esc(i.supplier)}</small></td><td>${i.stock}<small>${i.unit}s</small></td><td>${M.reserved(state,i.id)}</td><td><strong>${M.available(state,i.id)}</strong></td><td>${money(i.cost)}</td><td>${M.available(state,i.id)<=i.min?'<span class="badge cancelled">Reorder soon</span>':'<span class="badge ready">Healthy</span>'}<small>Reorder at ${i.min}</small></td><td><button class="button small" data-action="receive" data-id="${i.id}">+ Receive stock</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No matching components.</td></tr>'}</tbody></table></div><div class="table-bottom"><span>Available = on hand − reserved for active orders</span><span>${items.length} components</span></div></section>`;}
function hampers(){return heading('CONSIDERED COMBINATIONS','Gift hampers','Beautiful collections, with every component accounted for.',button('Build a hamper','new-hamper','',true))+`<div class="card-grid">${state.hampers.map(h=>{const c=M.cost(state,h.recipe);return `<article class="hamper-card"><div class="hamper-photo"><img src="../assets/${h.image}" alt="${esc(h.name)} concept photography"><span class="badge">${esc(h.category)}</span></div><div class="hamper-body"><h2>${esc(h.name)}</h2><p>${Object.keys(h.recipe).length} considered components</p><div class="hamper-stats"><div><strong>${money(h.price)}</strong><small>Selling price</small></div><div><strong>${money(c)}</strong><small>Material cost</small></div><div><strong>${Math.round((h.price-c)/h.price*100)}%</strong><small>Material margin</small></div></div>${Object.entries(h.recipe).map(([id,q])=>`<div class="recipe-row"><span>${esc(M.item(state,id).name)}</span><span>× ${q}</span></div>`).join('')}<div class="hamper-footer"><span>${M.capacity(state,h.recipe)} available to build</span><button class="button small" data-action="new-order" data-hamper="${h.id}">Create order ↗</button></div></div></article>`}).join('')}</div><p class="subheading" style="margin-top:18px">Material margin excludes labour, delivery, overhead and tax. Availability is shared across hampers that use the same components.</p>`;}
function corporate(){return heading('FOR THEIR PEOPLE. FOR THEIR BRAND.','Corporate gifting','From a considered brief to an approved collection.',button('New quotation','new-quote','',true))+`<section class="panel"><div class="quote-summary"><span>${state.quotes.filter(q=>q.status!=='Converted').length} opportunities in progress</span><strong>${money(state.quotes.filter(q=>q.status!=='Converted').reduce((n,q)=>n+q.qty*q.price,0))} potential order value</strong></div><div class="table-wrap"><table><thead><tr><th>QUOTATION / COMPANY</th><th>COLLECTION</th><th>GIFTS</th><th>VALUE</th><th>STATUS</th><th>DELIVER BY</th><th></th></tr></thead><tbody>${state.quotes.map(q=>`<tr><td><button class="order-id" data-action="quote-detail" data-id="${q.id}">${q.id}</button><small>${esc(q.company)}</small></td><td>${esc(M.hamper(state,q.hamper)?.name)}<small>${esc(q.occasion)}</small></td><td>${q.qty}</td><td>${money(q.qty*q.price)}</td><td>${badge(q.status)}</td><td>${date(q.due)}</td><td><button class="link-button" data-action="quote-detail" data-id="${q.id}">Open ↗</button></td></tr>`).join('')}</tbody></table></div></section><div class="bottom-grid"><section class="panel report-metric"><p class="eyebrow">A CLEAR APPROVAL PATH</p><h2>Brief. Approve. Prepare.</h2><p style="margin-top:12px">Create a quotation, record sample approval, then convert it into an order. Components are reserved only when the order is confirmed.</p></section><section class="panel report-metric"><p class="eyebrow">A REALISTIC DEMONSTRATION</p><h2>Big orders, honest availability.</h2><p style="margin-top:12px">Try The Finch Group’s 50-gift quotation. The demo will identify a stock shortage before accepting the order. Receive the needed components in Inventory to continue.</p></section></div>`;}
function dispatch(){return heading('THE FINISHING TOUCHES','Packing & dispatch','A clear path from reserved components to gifts on their way.',`<a href="#orders" class="button">View all orders ↗</a>`)+`<div class="kanban">${M.activeStatuses.map(status=>{const rows=state.orders.filter(o=>o.status===status);return `<section class="kanban-column"><div class="kanban-head">${status==='Confirmed'?'To prepare':status==='Packing'?'At the packing table':'Ready to leave'}<span>${rows.length}</span></div>${rows.map(o=>`<article class="job"><div class="job-top"><span>${o.id}</span><span>Due ${date(o.due)}</span></div><h3>${esc(o.customer)}</h3><p>${o.qty} × ${esc(M.hamper(state,o.hamper)?.name)}</p><div class="job-meta">${badge(o.channel)}${o.note?'<span class="badge">Gift note included</span>':''}</div><button class="button small" data-action="order-detail" data-id="${o.id}">View packing details ↗</button><button class="button primary small" data-action="advance" data-id="${o.id}">${nextLabel(status)} →</button></article>`).join('')||'<div class="empty" style="padding:28px 10px">All clear for now.</div>'}</section>`}).join('')}</div><p class="subheading" style="margin-top:20px">Dispatch consumes the reserved components once. No courier booking or customer message is sent in this demo.</p>`;}
function reports(){const rows=state.orders.filter(o=>o.status!=='Cancelled'),value=rows.reduce((n,o)=>n+o.qty*o.price,0),cost=rows.reduce((n,o)=>n+o.qty*o.cost,0);return heading('THE BUSINESS BEHIND THE BEAUTY','Studio reports','A useful view of your sample orders and stock.',button('Export orders','export'))+metrics()+`<div class="bottom-grid"><section class="panel report-metric"><p class="eyebrow">ORDER ECONOMICS</p><h2>Material contribution</h2><div class="big-number">${money(value-cost)}</div><p>Order value of ${money(value)} less material costs of ${money(cost)}. This is not net profit or recognised revenue; it excludes tax, labour, delivery, refunds and operating expenses.</p></section><section class="panel"><div class="panel-head"><h2>Order value by channel</h2></div><div class="margin-chart">${['Website','Corporate','Concierge'].map(ch=>{const v=rows.filter(o=>o.channel===ch).reduce((n,o)=>n+o.qty*o.price,0);return `<div class="chart-row"><span>${ch}</span><div class="bar-track"><div class="bar-fill" style="width:${value?v/value*100:0}%"></div></div><span>${value?Math.round(v/value*100):0}%</span></div><p style="font-size:10px;color:var(--muted)">${money(v)}</p>`}).join('')}</div></section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Stock valuation</h2><span class="subheading">Current material cost</span></div><div class="quote-summary"><span>${state.items.length} component types · ${state.orders.filter(o=>o.status==='Dispatched').length} dispatched orders</span><strong>${money(state.items.reduce((n,i)=>n+i.stock*i.cost,0))} on hand</strong></div></section>`;}
function render(){nav();main.innerHTML=({overview,orders,inventory,hampers,corporate,dispatch,reports}[view])();}
function setMenu(open){
 document.body.classList.toggle('nav-open',open);
 document.querySelector('.mobile-toggle').setAttribute('aria-expanded',String(open));
 document.querySelector('.nav-backdrop').hidden=!open;
 document.querySelector('.shell').inert=open;
 if(open)document.querySelector('.sidebar-close').focus();
 else document.querySelector('.mobile-toggle').focus();
}
document.addEventListener('click',e=>{if(e.target.closest('#sidebar a'))setMenu(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('nav-open'))setMenu(false);});
window.matchMedia('(max-width:680px)').addEventListener('change',()=>setMenu(false));
function navigate(){const next=location.hash.slice(1);view=names[next]?next:'overview';search='';statusFilter='All';setMenu(false);render();}
function open(title,body,eyebrow='MAISON AURELLE · STUDIO'){if(!dialog.open)returnFocus=document.activeElement;document.querySelector('#dialog-inner').innerHTML=`<div class="dialog-head"><div><p class="eyebrow">${eyebrow}</p><h2 id="dialog-title">${esc(title)}</h2></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('input,select,.close')?.focus();}
const options=(selected)=>state.hampers.map(h=>`<option value="${h.id}" ${h.id===selected?'selected':''}>${esc(h.name)}</option>`).join('');
const formEnd=(label)=>`<p class="form-error" role="alert" hidden></p><div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary" type="submit">${label} →</button></div>`;
function newOrder(id){open('A new thoughtful gesture.',`<form id="order-form"><div class="form-grid"><label class="field full">Customer or company<input name="customer" required maxlength="100" placeholder="e.g. Ananya Mehta"></label><label class="field full">Gift collection<select name="hamper">${options(id)}</select></label><label class="field">Number of gifts<input name="qty" type="number" min="1" max="10000" value="1" required></label><label class="field">Deliver by<input name="due" type="date" value="2026-11-05" required></label><label class="field">Sales channel<select name="channel"><option>Concierge</option><option>Website</option><option>Corporate</option></select></label><label class="field">Sample payment status<select name="payment"><option>Pending</option><option>Deposit</option><option>Paid</option></select></label><label class="field full">Gift message<textarea name="note" maxlength="500" placeholder="A few words, from them…"></textarea></label></div><div class="form-summary" id="order-summary"></div><p class="subheading">Creates a sample order and reserves components. No payment is collected.</p>${formEnd('Create & reserve')}</form>`,'ORDERS / NEW');updateSummary();}
function updateSummary(){const f=dialog.querySelector('#order-form')||dialog.querySelector('#quote-form');if(!f)return;const h=M.hamper(state,f.elements.hamper.value),q=Number(f.elements.qty.value)||0;const el=dialog.querySelector('#order-summary');el.innerHTML=`<div><small>Illustrative total · ${q} gifts</small><strong>${money(h.price*q)}</strong></div><div><small>Available to reserve</small><strong>${M.capacity(state,h.recipe)} <span style="font:11px var(--sans)">gifts</span></strong></div>`;}
function orderDetail(id){const o=state.orders.find(x=>x.id===id);if(!o)return;open(o.id+' · '+o.customer,`<div class="steps">${['Confirmed','Packing','Ready','Dispatched'].map((s,i)=>`<div class="step ${['Confirmed','Packing','Ready','Dispatched'].indexOf(o.status)>=i?'done':''}">${s}</div>`).join('')}</div><div class="detail-grid"><div><span>Collection</span><strong>${esc(M.hamper(state,o.hamper)?.name)}</strong></div><div><span>Quantity / value</span><strong>${o.qty} gifts · ${money(o.qty*o.price)}</strong></div><div><span>Due date</span><strong>${date(o.due)} · ${esc(o.channel)}</strong></div><div><span>Payment (sample)</span>${badge(o.payment)}</div></div><p class="section-label">Packing list · entire order</p><div class="detail-list">${Object.entries(o.recipe).map(([id,q])=>`<div class="detail-line"><span>${esc(M.item(state,id).name)}</span><strong>${q*o.qty} ${M.item(state,id).unit}${q*o.qty===1?'':'s'}</strong></div>`).join('')}</div>${o.note?`<p class="section-label">Personal message</p><div class="note">${esc(o.note)}</div>`:''}<p class="form-error" role="alert" hidden></p><div class="form-actions">${M.activeStatuses.includes(o.status)?`<button class="button danger" data-action="cancel-order" data-id="${id}">Cancel order</button><button class="button primary" data-action="advance" data-id="${id}">${nextLabel(o.status)} →</button>`:badge(o.status)}</div>`,'ORDER / DETAILS');}
function receive(id){const i=M.item(state,id);open('Receive stock',`<p class="tour-intro">${esc(i.name)}</p><form id="receive-form" data-id="${id}"><div class="detail-grid"><div><span>Supplier</span><strong>${esc(i.supplier)}</strong></div><div><span>Currently available</span><strong>${M.available(state,id)} ${i.unit}s</strong></div></div><label class="field">Quantity received (${i.unit}s)<input name="qty" type="number" min="1" max="100000" value="25" required></label><p class="subheading">A demo stock receipt. No purchase order or supplier payment is created.</p>${formEnd('Receive stock')}</form>`,'INVENTORY / RECEIPT');}
function newHamper(){open('Create a considered collection.',`<form id="hamper-form"><div class="form-grid"><label class="field full">Hamper name<input name="name" maxlength="80" required placeholder="e.g. The Festive Edit"></label><label class="field full">Selling price (INR)<input name="price" type="number" min="1" max="1000000" value="4990" required></label></div><p class="section-label">Select components · quantity per gift</p>${state.items.map(i=>`<label class="recipe-input"><span>${esc(i.name)}<small style="display:block;color:var(--muted)">${money(i.cost)} / ${i.unit}</small></span><input name="component-${i.id}" type="number" min="0" max="100" value="0" aria-label="${esc(i.name)} quantity"></label>`).join('')}<div class="form-summary" id="recipe-summary"><small>Select components to calculate costs.</small></div>${formEnd('Create hamper')}</form>`,'COLLECTIONS / BUILDER');}
function recipeSummary(){const f=dialog.querySelector('#hamper-form');if(!f)return;const recipe={};state.items.forEach(i=>{const q=Number(f.elements['component-'+i.id].value);if(q>0)recipe[i.id]=q;});const cost=M.cost(state,recipe),price=Number(f.elements.price.value);dialog.querySelector('#recipe-summary').innerHTML=`<div><small>Material cost / gift</small><strong>${money(cost)}</strong></div><div><small>Material margin</small><strong>${price?Math.round((price-cost)/price*100):0}%</strong></div><div><small>Buildable now</small><strong>${M.capacity(state,recipe)}</strong></div>`;}
function newQuote(){open('Something entirely their own.',`<form id="quote-form"><div class="form-grid"><label class="field full">Company<input name="company" maxlength="100" placeholder="Company or organisation" required></label><label class="field full">Occasion<input name="occasion" maxlength="100" placeholder="e.g. Festive appreciation" required></label><label class="field full">Gift collection<select name="hamper">${options()}</select></label><label class="field">Quantity<input name="qty" type="number" value="25" min="1" max="10000" required></label><label class="field">Deliver by<input name="due" type="date" value="2026-11-12" required></label><label class="field full">Personalisation brief<textarea name="note" maxlength="1000" placeholder="Branding, colours, gift messages…"></textarea></label></div><div class="form-summary" id="order-summary"></div><p class="subheading">Quotations do not reserve stock. Availability is checked on conversion.</p>${formEnd('Save quotation')}</form>`,'CORPORATE / QUOTATION');updateSummary();}
function quoteDetail(id){const q=state.quotes.find(x=>x.id===id),h=M.hamper(state,q.hamper);open(q.id+' · '+q.company,`<div class="detail-grid"><div><span>Occasion</span><strong>${esc(q.occasion)}</strong></div><div><span>Approval stage</span>${badge(q.status)}</div><div><span>Collection</span><strong>${esc(h.name)}</strong></div><div><span>Quantity / due date</span><strong>${q.qty} gifts · ${date(q.due)}</strong></div></div><div class="form-summary"><div><small>Quoted total · ${money(q.price)} per gift</small><strong>${money(q.qty*q.price)}</strong></div><div><small>Available now</small><strong>${M.capacity(state,h.recipe)} gifts</strong></div></div><p class="section-label">Personalisation brief</p><div class="note">${esc(q.note||'No additional instructions.')}</div><p class="form-error" role="alert" hidden></p><div class="form-actions"><button class="button" data-action="download-quote" data-id="${id}">Download brief ↓</button>${q.status==='Converted'?`<button class="button primary" data-action="order-detail" data-id="${q.orderId}">View order ↗</button>`:q.status==='Approved'?`<button class="button primary" data-action="convert-quote" data-id="${id}">Convert to order →</button>`:`<button class="button primary" data-action="approve-quote" data-id="${id}">Record approval →</button>`}</div><p class="subheading">Demo approval only. No quotation or message is sent to the client.</p>`,'CORPORATE / DETAILS');}
function tour(){open('Welcome to the gifting studio.',`<p class="tour-intro">A small boutique. A beautifully connected way to work.</p>${[['01','Create a gift order','Choose a hamper and quantity. The studio checks component availability and reserves what you need.'],['02','See the details behind the gift','Explore Inventory and receive presentation boxes to increase the number of hampers you can build.'],['03','Move it through the studio','Start packing, mark ready, then dispatch. Reserved stock becomes consumed stock exactly once.'],['04','Explore a bigger gesture','Approve a corporate quotation and convert it to an order, or build a new hamper from individual components.']].map(([n,t,p])=>`<div class="tour-step"><b>${n}</b><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}<p class="subheading" style="margin-top:18px">All people, transactions and approvals are sample data. Changes stay in this browser. Reset the workspace at any time.</p><div class="form-actions"><button class="button primary" data-action="new-order">Try your first order →</button></div>`,'AN INTERACTIVE ERP DEMONSTRATION');}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCsv(){let rows;if(view==='inventory')rows=[['SKU','Component','On hand','Reserved','Available','Unit cost INR'],...state.items.map(i=>[i.sku,i.name,i.stock,M.reserved(state,i.id),M.available(state,i.id),i.cost])];else rows=[['Order','Customer','Collection','Quantity','Value INR','Status','Payment','Due'],...state.orders.map(o=>[o.id,o.customer,M.hamper(state,o.hamper)?.name,o.qty,o.qty*o.price,o.status,o.payment,o.due])];const csv=rows.map(row=>row.map(v=>{let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');download('aurelle-'+(view==='inventory'?'inventory':'orders')+'.csv','\ufeff'+csv,'text/csv;charset=utf-8');toast('Your demo export is ready.');}
function error(err){const el=dialog.querySelector('.form-error');if(dialog.open&&el){el.textContent=err.message;el.hidden=false;}else toast(err.message);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter){statusFilter=b.dataset.filter;render();return;}const id=b.dataset.id;try{switch(b.dataset.action){case'menu':setMenu(!document.body.classList.contains('nav-open'));break;case'close-menu':setMenu(false);break;case'close':dialog.close();break;case'tour':tour();break;case'new-order':newOrder(b.dataset.hamper);break;case'order-detail':orderDetail(id);break;case'receive':receive(id);break;case'new-hamper':newHamper();break;case'new-quote':newQuote();break;case'quote-detail':quoteDetail(id);break;case'advance':{const o=M.advance(state,id);save();render();if(dialog.open)orderDetail(id);toast(`${id} · ${o.status.toLowerCase()}`);break;}case'cancel-order':open('Cancel this order?',`<p>The reserved components for ${esc(id)} will become available again.</p><div class="form-actions"><button class="button" data-action="order-detail" data-id="${id}">Keep order</button><button class="button danger" data-action="confirm-cancel" data-id="${id}">Cancel order</button></div>`);break;case'confirm-cancel':M.cancel(state,id);save();dialog.close();render();toast('Order cancelled. Reserved components released.');break;case'approve-quote':{const q=state.quotes.find(x=>x.id===id);q.status='Approved';M.log(state,`${id} sample approval recorded`);save();render();quoteDetail(id);break;}case'convert-quote':{const q=state.quotes.find(x=>x.id===id);if(q.status!=='Approved')throw Error('Record approval before converting.');const o=M.addOrder(state,{...q,customer:q.company,channel:'Corporate',payment:'Pending'});o.price=q.price;q.status='Converted';q.orderId=o.id;save();render();orderDetail(o.id);toast(`${o.id} created from ${id}`);break;}case'download-quote':{const q=state.quotes.find(x=>x.id===id);download(q.id+'-gifting-brief.txt',`MAISON AURELLE — DEMO QUOTATION\n${q.id} | ${q.company}\n${q.qty} × ${M.hamper(state,q.hamper).name}\nQuoted total: ${money(q.qty*q.price)}\nDelivery date: ${q.due}\n\n${q.note}\n\nIllustrative brief only. No approval request, order, payment or delivery is sent. Tax and shipping excluded.`);toast('Brief downloaded. Nothing was sent to the client.');break;}case'export':exportCsv();break;case'reset':open('A fresh beginning?',`<p>Reset this browser’s demo orders, quotations and inventory to the original sample data?</p><div class="form-actions"><button class="button" data-action="close">Keep my changes</button><button class="button primary" data-action="confirm-reset">Reset demo</button></div>`);break;case'confirm-reset':state=M.seed();save();dialog.close();search='';statusFilter='All';render();toast('Demo reset. A fresh start for the studio.');break;}}catch(err){error(err);}});
document.addEventListener('input',e=>{if(e.target.matches('.search')){search=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('.search');input.focus();input.setSelectionRange(pos,pos);}if(e.target.closest('#order-form,#quote-form'))updateSummary();if(e.target.closest('#hamper-form'))recipeSummary();});
document.addEventListener('change',e=>{if(e.target.closest('#order-form,#quote-form'))updateSummary();});
document.addEventListener('submit',e=>{const f=e.target;if(!['order-form','receive-form','hamper-form','quote-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));try{if(f.id==='order-form'){const o=M.addOrder(state,data);save();render();orderDetail(o.id);toast(`${o.id} created. Components reserved.`);}if(f.id==='receive-form'){M.receive(state,f.dataset.id,data.qty);save();dialog.close();render();toast('Stock received. Hamper availability updated.');}if(f.id==='hamper-form'){const recipe={};state.items.forEach(i=>recipe[i.id]=Number(data['component-'+i.id]));M.addHamper(state,{...data,recipe});save();dialog.close();location.hash='hampers';if(view==='hampers')render();toast('Your new hamper is ready for orders.');}if(f.id==='quote-form'){const qty=Number(data.qty);if(!data.company.trim()||!data.occasion.trim()||!Number.isInteger(qty)||qty<1||qty>10000)throw Error('Add a company, occasion and valid quantity.');const h=M.hamper(state,data.hamper);const q={...data,id:M.nextId(state.quotes,'QT-',26),qty,price:h.price,status:'Draft'};state.quotes.unshift(q);M.log(state,`${q.id} prepared for ${q.company}`);save();render();quoteDetail(q.id);toast('Quotation saved as a draft.');}}catch(err){error(err);}});
dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();else main.focus();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',navigate);navigate();
})();
